22	// Internal function to map simple integer (kbps) to TWAI driver structures
23	static esp_err_t get_timing_config(uint32_t baudrate, twai_timing_config_t* t_config) {
24	    switch(baudrate) {
25	        case 20: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_20KBITS(); break;     // 20000 bps
26	        case 50: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_50KBITS(); break;     // 50000 bps        
27	        case 100: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_100KBITS(); break;   // 100000 bps
28	        case 125: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_125KBITS(); break;   // 125000 bps
29	        case 250: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_250KBITS(); break;   // 250000 bps
30	        case 500: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_500KBITS(); break;   // 500000 bps
31	        case 800: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_800KBITS(); break;   // 800000 bps
32	        case 1000: *t_config = (twai_timing_config_t)TWAI_TIMING_CONFIG_1MBITS();  break;   // 1000000 bps
33	        default:
34	            ESP_LOGE(TAG, "Unsupported baudrate: %" PRIu32 " kbps", baudrate);
35	            return ESP_ERR_INVALID_ARG;
36	    }
37	    return ESP_OK;
38	}
