40	static void handle_rx_message(twai_message_t message) {
41	    // log received message for debugging
42	    // ESP_LOGI(TAG, "Received CAN message: ID=0x%03" PRIX32 ", DLC=%d", message.identifier, message.data_length_code);    
43	    
44	    // Switch-case based parsing logic based on CAN Message Identifier
45	    switch (message.identifier) {
46	        
47	        case 0x06214000: { // Ignition Status & Fuel Level
48	            uint8_t new_ignition = ((uint8_t)message.data[2] & 0x40) ? 1 : 0;
49	            
50	            if (current_can_data.ignition == 0 && new_ignition == 1) {
51	                can_app_load_fuel_consumption();
52	                ui_backlight_sync_ignition(new_ignition);
53	                sd_card_on_ignition_on();
54	            } else if (current_can_data.ignition == 1 && new_ignition == 0) {
55	                can_app_save_fuel_consumption();
56	                ui_backlight_sync_ignition(new_ignition);
57	                sd_card_on_ignition_off();
58	            }
59	            
60	            current_can_data.ignition = new_ignition;
61	            
62	            uint8_t raw_fuel_data = (uint8_t)message.data[5] & 0x7F;
63	            if (raw_fuel_data != 0x7F)
64	                current_can_data.fuel_level = (uint8_t)raw_fuel_data;
65	            break;
66	        }
67	
68	        case 0x04394000: { // Vehicle Speed
69	            if (current_can_data.ignition) {
70	                uint16_t raw_data = (uint16_t)((message.data[0] << 8) | message.data[1]);
71	                if (raw_data != 0xFFFF)
72	                    current_can_data.speed = (uint8_t)(raw_data >> 4);
73	            }   
74	            else {
75	                current_can_data.speed = 0;                
76	            }         
77	            break;
78	        }
79	
80	        case 0x04394100: { // Throttle Pedal Position (0-0xFF)            
81	                current_can_data.throttle_pedal = (uint8_t)message.data[3];
82	            break;
83	        }
84	
85	        case 0x04214001: { // RPM & Fuel Consumption & Oil Temperature``
86	            if (current_can_data.ignition) {
87	                uint16_t raw_data = (uint16_t)((message.data[6] << 8) | message.data[5]);
88	                if (raw_data != 0xFFFF)
89	                    current_can_data.rpm = (uint16_t)(raw_data >> 3);
90	
91	                raw_data = (uint16_t)((message.data[4] << 8) | message.data[5]);
92	                if (raw_data != 0xFFFF) {
93	                    // 30,51 nL/bit
94	                    CAN_fuel_dose += raw_data;
95	                    
96	                    // if CAN_fuel_dose exceeds 1 mL (1000000 nL), increment fuel_consumption
97	                    if (CAN_fuel_dose >= 32777) { // 32776 bits * 30.51 nL/bit ≈ 1 mL
98	                        CAN_fuel_dose *= 15621;
99	                        CAN_fuel_dose >>= 9;
100	                        current_can_data.fuel_consumption += (float) (CAN_fuel_dose / 1000000.0f);
101	                        CAN_fuel_dose = 0; // reset accumulator
102	                    }
103	
104	                }
105	            }
106	            else {
107	                current_can_data.rpm = 0;                
108	            }
109	            if (message.data[7] != 0xFF)
110	                current_can_data.rear_gear = ((uint8_t)message.data[7] & 0x04) ? 1 : 0;
111	            current_can_data.oil_temp = (int8_t) (message.data[3] - 40);
112	            break;
113	        }
114	
115	        case 0x0C014003: { // Total Distance [km] & Range[km]            
116	            uint32_t raw_data= (__builtin_bswap32(*(uint32_t*)message.data)) & 0xFFFFF;
117	            if (raw_data != 0xFFFFF)
118	                current_can_data.t_distance = raw_data;
119	
120	            raw_data = (uint16_t)(((message.data[4] << 8) | message.data[5]) & 0x7FFF);
121	            if (raw_data != 0x7FFF)
122	                current_can_data.range = raw_data;
123	            break;
124	        }
125	
126	
127	        case 0x03029000: { // Brake Pedal Position
128	            uint16_t raw_data = (uint16_t)(((message.data[5] << 8) | message.data[6]) & 0xFFF);
129	            if (raw_data != 0xFFF)
130	                current_can_data.brake_pedal = (uint16_t)raw_data; // 0-0x3FF
131	            break;
132	        }
133	
134	        case 0x06314000: { // ESP Status
135	            uint8_t raw_data = (uint8_t)message.data[5] & 0xFF;    
136	            if (raw_data != 0xFF)
137	                current_can_data.esp_stat = raw_data & 0x03; // 0 - normal, 2 - sport, 3 - traction
138	            else
139	                current_can_data.esp_stat = 0;
140	            break;
141	        }
142	
143	        default:
144	            return; 
145	    }
146	    
147	    // Update timestamp indicating new valid data arrived (update only if known ID matched)
148	    current_can_data.timestamp = (uint32_t)(esp_timer_get_time() / 1000);
149	}
