151	void can_app_load_fuel_consumption(void) {
152	    nvs_handle_t my_handle;
153	    esp_err_t err = nvs_open("storage", NVS_READONLY, &my_handle);
154	    if (err == ESP_OK) {
155	        uint32_t saved_fuel_u32 = 0;
156	        err = nvs_get_u32(my_handle, "fuel_cons", &saved_fuel_u32);
157	        if (err == ESP_OK) {
158	            float saved_fuel;
159	            memcpy(&saved_fuel, &saved_fuel_u32, sizeof(float)); // Interpret the uint32_t bits as float
160	            current_can_data.fuel_consumption = saved_fuel;
161	            last_saved_fuel = saved_fuel; // Ustaw tak, by nie dublować zapisu
162	            ESP_LOGI(TAG, "Loaded fuel consumption from NVS: %.3f", saved_fuel);
163	        }
164	        nvs_close(my_handle);
165	    } else {
166	        ESP_LOGI(TAG, "No NVS data found for fuel consumption (first boot or formatted).");
167	    }
168	}
