170	void can_app_save_fuel_consumption(void) {
171	    if (CAN_fuel_dose > 0) {
172	        CAN_fuel_dose *= 15621;
173	        CAN_fuel_dose >>= 9;
174	        current_can_data.fuel_consumption += (float)(CAN_fuel_dose / 1000000.0f);
175	        CAN_fuel_dose = 0; // reset accumulator
176	    }
177	
178	    if (current_can_data.fuel_consumption == last_saved_fuel) {
179	        return; // No need to save if not changed
180	    }
181	
182	    nvs_handle_t my_handle;
183	    esp_err_t err = nvs_open("storage", NVS_READWRITE, &my_handle);
184	    if (err == ESP_OK) {
185	        uint32_t fuel_u32;
186	        memcpy(&fuel_u32, &current_can_data.fuel_consumption, sizeof(float)); // Interpret the float bits as uint32_t
187	        err = nvs_set_u32(my_handle, "fuel_cons", fuel_u32);
188	        if (err == ESP_OK) {
189	            err = nvs_commit(my_handle);
190	            last_saved_fuel = current_can_data.fuel_consumption;
191	            ESP_LOGI(TAG, "Saved fuel consumption to NVS: %.3f", current_can_data.fuel_consumption);
192	        }
193	        nvs_close(my_handle);
194	    } else {
195	        ESP_LOGE(TAG, "Error opening NVS handle: %s", esp_err_to_name(err));
196	    }
197	}
